
(function(){
  var R={'ELEC':'data:image/jpeg;base64,',
    'PLUMB':'data:image/jpeg;base64,',
    'ROOF':'data:image/jpeg;base64,',
    'TEAM':'data:image/jpeg;base64,'};
  function applyImgs(){
    document.querySelectorAll('[data-img]').forEach(function(el){
      var s=R[el.dataset.img];
      if(!s)return;
      if(el.tagName==='IMG')el.src=s;
      else el.style.backgroundImage='url('+s+')';
    });
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',applyImgs);
  else applyImgs();
})();

